export const replacedPhoneModels = Object.freeze([...new Set(retailInventory.filter(item => item.isPhone).map(item => `${item.brand}|${item.model}`))]);

export const retailPhoneProducts = Object.freeze(retailInventory.filter(item => item.isPhone).map(item => ({
  brand: item.brand,
  model: item.model,
  slug: item.slug,
  route: `/${item.slug}`,
  family: item.brand === "Apple" ? "iPhone" : item.brand === "Google" ? "Pixel" : "Galaxy",
  listingPending: false,
  specificationsPending: !item.specifications,
  variants: item.variants.map(variant => ({
    storage: variant.storage,
    price: variant.price,
    color: variant.color || null,
    ram: variant.ram || null,
    warranty: variant.warranty || null,
    activationStatus: variant.activationStatus || null,
    availability: variant.price === null ? "Confirm price and availability" : "Confirm availability",
    priceNeedsExtraConfirmation: variant.price === null,
    oldPrice: null
  })),
  defaultStorage: item.variants[0]?.storage || "Confirm variant",
  colors: item.colors.length ? item.colors : ["Ask for today’s available colours"],
  conditions: [item.condition],
  images: item.gallery || (item.image ? [item.image] : []),
  stockStatus: "Confirm the exact unit and availability before payment",
  easyBuyEligible: true,
  swapEligible: true,
  warranty: "Confirm written terms for the exact unit",
  batteryHealth: "Ask for battery-condition details when considering a used unit.",
  specificationsSource: item.specificationsSource,
  specifications: item.specifications || {
    display: "Confirm the exact unit’s display",
    camera: "Confirm the exact camera configuration",
    processor: "Confirm the exact model specification",
    network: "Confirm network compatibility",
    security: "Confirm supported security features",
    sim: "Confirm SIM options for the exact unit"
  },
  description: `Choose a listed ${item.condition.toLowerCase()} ${item.model} variant, then confirm exact stock, colour, warranty and delivery with Lisa Electronics.`,
  seoTitle: `Buy ${item.model} ${item.condition} in Nigeria | Lisa Electronics`,
  metaDescription: `View ${item.condition.toLowerCase()} ${item.model} storage and colour options at Lisa Electronics. Confirm stock, warranty, Easy Buy, swap and delivery details before payment.`
})));
